/// An event's payload. Types and versions this build does not know decode to
/// `unknown`, because a daemon can be newer than the app.
public enum EventPayload: Hashable, Sendable {
  case artifactPublished(ArtifactPublished)
  case turnStarted(TurnStarted)
  case turnEnded(TurnEnded)
  case messageDelta(MessageDelta)
  case message(Message)
  case thinking(Thinking)
  case toolCall(ToolCall)
  case fileChange(FileChange)
  case approvalRequested(ApprovalRequested)
  case approvalResolved(ApprovalResolved)
  case question(Question)
  case usage(Usage)
  case error(Error)
  case modeChanged(ModeChanged)
  case modelChanged(ModelChanged)
  case contextUsage(ContextUsage)
  case todoList(TodoList)
  case subagent(Subagent)
  case sessionDelegated(SessionDelegated)
  case unknown(type: EventType, v: UInt16)
}

extension Event {
  /// Decodes `payload` according to `type` and `v`.
  public func decodedPayload() throws -> EventPayload {
    switch (type.rawValue, v) {
    case ("artifact.published", 1): return .artifactPublished(try payload.decode(ArtifactPublished.self))
    case ("turn.started", 1): return .turnStarted(try payload.decode(TurnStarted.self))
    case ("turn.ended", 1): return .turnEnded(try payload.decode(TurnEnded.self))
    case ("message.delta", 1): return .messageDelta(try payload.decode(MessageDelta.self))
